SELECT o.recordvault, o.dealcount, o.dealquote, o.orderflow
FROM orders o
LIMIT 10;

SELECT oe.ordersmark, oe.fillcount, oe.remaincount, oe.fillsum
FROM orderexecutions oe
LIMIT 10;

-- Count distinct orders from this query
SELECT COUNT(DISTINCT oe.ordersmark) as order_count
FROM orderexecutions oe;
